+#define MLX90393_CMD_SW        0x20	/* Start Wake-up on Change Mode */
+#define MLX90393_CMD_SM        0x30	/* Start Single Measurement Mode */
+#define MLX90393_CMD_RM        0x40	/* Read Measurement */
+#define MLX90393_CMD_RR        0x50	/* Read Register */
